function editSceneItem(action,x,y){if(!sim||sim.mode!=='scene')return false;const a=selectedActor(),i=Number(editSelection.slice(1)),p=/^o\d+$/.test(editSelection)?sim.props[i]:null;if(!a&&!p)return false;if(action==='remove'){rememberLayout();if(a){sim.sceneActors.splice(i,1);sim.mobs=sim.mobs.filter(m=>m.savedPlacement!==a.placement)}else sim.props.splice(i,1);editSelection='all';}else{if(action==='duplicate'&&(a?sim.sceneActors.length>=MAX_MOBS:sim.props.length>=32))return false;const pt=safePoint(x,y);if(!pt&&a){notice='Mesto je zauzeto.';return false}if(p){const next=S().cleanProps([{...p,x,y}],sim.world)[0];if(!next||(next.kind!=='bridge'&&S().blocked(sim.props.filter((q,j)=>action==='duplicate'||j!==i),next.x,next.y,25))||[sim.p,...sim.mobs,...sim.visitors.values(),...sim.sceneActors.map(q=>q.placement)].some(v=>S().blocked([next],v.x,v.y,14))){notice='Mesto je zauzeto.';return false}rememberLayout();if(action==='duplicate'){sim.props.push(next);editSelection='o'+(sim.props.length-1)}else sim.props[i]=next;}else{rememberLayout();const old=a.placement,placement={...old,...pt};if(action==='duplicate'){const n={spec:a.spec,placement};sim.sceneActors.push(n);const m=entity(n.spec,sim.wave,pt.x,pt.y,placement);m.savedPlacement=placement;F().bind(m,sim.relations);sim.mobs.push(m);editSelection='a'+(sim.sceneActors.length-1)}else{a.placement=placement;const m=sim.mobs.find(v=>v.savedPlacement===old);if(m){m.savedPlacement=placement;m.placement={...placement};m.x=pt.x;m.y=pt.y;m.brain.target=null;m.brain.nextSense=0;I().cancelCast(m)}}}}refreshSandbox();notice='Scena izmenjena.';return true;}
function restartScene(battle=sim?.sceneBattle){if(sim?.mode!=='scene')return false;const s=sim;s.mobs=s.sceneActors.map(a=>{const p=a.placement,m=entity(a.spec,s.wave,p.x,p.y,p);m.savedPlacement=p;F().bind(m,s.relations);return m});for(const p of [s.p,...s.visitors.values()]){const free=S().freePoint(s.props,p.x,p.y,s.world);if(free.x!==p.x||free.y!==p.y){p.x=free.x;p.y=free.y;p.warp=(p.warp||0)+1;if(p!==s.p)window.NS177_WORKSHOP?.teleportGuest?.(p.workshopSeat,free)}}s.p.s=effective(s.p.c,s.wave);s.p.hp=s.p.s.hp;A()?.init(s.p);s.p.brain.target=null;s.p.brain.retaliate=null;s.p.cd=s.p.swing=0;s.p.revives=0;s.p.downSince=null;s.p.protectedUntil=0;for(const v of s.visitors.values()){v.brain.target=null;v.brain.retaliate=null;v.hp=v.s.hp;v.cd=v.swing=0;v.revives=0;v.downSince=null;v.protectedUntil=0;A()?.init(v);}s.usedProps=new WeakSet();s.propHealth=new WeakMap();s.nextSpawnAt=0;s.spawnCursor=0;s.soundMask=0;for(const a of [s.p,...s.visitors.values()]){a.portalAt=0;a.propAttackAt=0}s.propCheckAt=0;s.fx=[];s.drops=[];s.xp=s.kills=s.damageDone=s.damageTaken=0;s.time=0;s.voiceQueue.length=0;s.paused=false;s.sceneBattle=!!battle;s.forceObserve=!battle;notice='Borba resetovana · raspored sačuvan';return true;}
